    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    epsilon = 1e-6\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    cost_gap = batch.get('cost_gap', ops.abs(cost_a - cost_b))\n    diff = log_prob_w - log_prob_l\n    cost_diff = cost_a - cost_b\n    penalty = ops.logsigmoid( - diff * cost_diff / (ops.abs(cost_gap) + epsilon) )\n    return ops.sum( penalty * weight ) / ops.size( penalty )"
}

{
  "name": "pairwise_cost_gap_loss",
  "intuition": "This loss encourages the model to assign higher log probabilities to lower-cost options by penalizing pairs where the higher-cost option has a higher likelihood. Using the cost gap as a signal aligns the model's preferences with cost minimization, promoting better ranking of options in RL4CO tasks.",
  "pseudocode": "loss = mean over pairs of max(0, log_prob_l - log_prob_w + alpha * cost_gap)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "cost_difference",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "cost_ordering",
