{
  "name": "pairwise_exponential_advantage_difference_fixed_grad",
  "intuition": "Exponentially weight the advantage difference with alpha scaling; alpha is a fixed scalar without requires_grad to preserve gradients.",
  "pseudocode": "adv_diff = advantage_w - advantage_l\nscaled_adv = exp(-alpha * adv_diff)\nloss = weight * scaled_adv\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_exponential",
    "signal_family": "advantage_gap",
    "link_family": "exp",
    "agg_family": "mean",
    "constraint_family": "none",
    "other_hparams": "alpha (float scalar)"
  },
  "operators_used": ["sub", "exp", "mul", "mean", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch[\"advantage_w\"]\n    adv_l = batch[\"advantage_l\"]\n    weight = batch[\"weight\"]\n    alpha_val = extra.get(\"alpha\", extra.get(\"hyperparams\", {}).get(\"alpha\", 1.0))\n    alpha_tensor = adv_w.new_full((), alpha_val)  # scalar tensor without grad\n    adv_diff = ops.sub(adv_w, adv_l)\n    scaled_adv = ops.exp(ops.mul(ops.neg(alpha_tensor), adv_diff))\n    loss = ops.mul(weight, scaled_adv)\n    return loss.mean()"
}

